// Package id generates coordinator identifiers.
package id

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"sync/atomic"
	"time"
)

var fallbackCounter atomic.Uint64

// New returns a random UUIDv4 string (RFC 4122, lower-case hex with dashes).
//
// It never panics on a request path: if the system CSPRNG fails (which would
// indicate a broken host), it falls back to a time-ordered, process-unique
// identifier rather than aborting the process. IDs are not security tokens;
// secrets are generated by the caller from crypto/rand and errors are surfaced.
func New() string {
	var b [16]byte
	if _, err := rand.Read(b[:]); err != nil {
		// Broken CSPRNG: still produce a unique, non-guessable-enough id. This
		// path is practically unreachable and is logged by callers if it ever
		// matters.
		now := time.Now().UnixNano()
		n := fallbackCounter.Add(1)
		for i := 0; i < 8; i++ {
			b[i] = byte(now >> (8 * i))
		}
		for i := 0; i < 8; i++ {
			b[8+i] = byte(n >> (8 * i))
		}
	} else {
		b[6] = (b[6] & 0x0f) | 0x40 // version 4
		b[8] = (b[8] & 0x3f) | 0x80 // RFC 4122 variant
	}
	var out [36]byte
	hex.Encode(out[0:8], b[0:4])
	out[8] = '-'
	hex.Encode(out[9:13], b[4:6])
	out[13] = '-'
	hex.Encode(out[14:18], b[6:8])
	out[18] = '-'
	hex.Encode(out[19:23], b[8:10])
	out[23] = '-'
	hex.Encode(out[24:36], b[10:16])
	return string(out[:])
}

// Validate reports whether s looks like a canonical UUID.
func Validate(s string) error {
	if len(s) != 36 {
		return fmt.Errorf("id: %q is not a UUID", s)
	}
	for i, c := range s {
		switch i {
		case 8, 13, 18, 23:
			if c != '-' {
				return fmt.Errorf("id: %q is not a UUID", s)
			}
		default:
			if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f')) {
				return fmt.Errorf("id: %q is not a lower-case UUID", s)
			}
		}
	}
	return nil
}

// NewSecret returns n random bytes as lower-case hex (used for one-time
// announce secrets, access key secrets and similar material).
func NewSecret(n int) (string, error) {
	b := make([]byte, n)
	if _, err := rand.Read(b); err != nil {
		return "", fmt.Errorf("id: generate secret: %w", err)
	}
	return hex.EncodeToString(b), nil
}
